import React from 'react';

export function CategoryChart() {
  return <section className="panel category-panel"><div className="panel-heading"><div><h2>Reports by category</h2><p>Distribution of submitted cases</p></div><button className="text-button">This month⌄</button></div><div className="category-bars">{[['Illegal dumping',46,'#185835'],['Water pollution',30,'#4d9b78'],['Air pollution',17,'#e7aa45'],['Unsafe disposal',7,'#c8d9d3']].map(([label, value, color]) => <div className="bar-row" key={label}><span>{label}</span><div className="bar-track"><i style={{ width: `${value}%`, background: color }}/></div><b>{value}%</b></div>)}</div></section>;
}

export function ResolutionChart() {
  return <section className="panel response-panel"><div className="panel-heading"><div><h2>Regional response</h2><p>Case resolution performance</p></div><span className="period">This month⌄</span></div><div className="response-content"><div className="ring"><div><b>78%</b><small>resolution rate</small></div></div><div className="response-stats"><div><span>Average response time</span><b>4.2 <small>hrs</small></b></div><div><span>Cases resolved</span><b>24 <small>of 31</small></b></div><div><span>Citizen satisfaction</span><b>4.8 <small>/ 5.0</small></b></div></div></div></section>;
}

export default function AnalyticsCharts() {
  return <div className="analytics-grid"><CategoryChart/><section className="panel chart-panel"><div className="panel-heading"><div><h2>Monthly resolution rate</h2><p>Cases resolved within each month</p></div><span className="period">2025⌄</span></div><div className="chart-legend"><span><i/> Resolution rate</span></div><div className="line-chart"><div className="y-labels"><span>100%</span><span>75%</span><span>50%</span><span>25%</span><span>0%</span></div><div className="chart-area"><div className="gridline g1"/><div className="gridline g2"/><div className="gridline g3"/><div className="gridline g4"/><svg viewBox="0 0 500 180" preserveAspectRatio="none"><path d="M0 130 C45 120 50 100 100 108 S165 85 200 98 S260 60 300 75 S360 64 400 57 S455 34 500 42" fill="none" stroke="#185835" strokeWidth="3"/><path d="M0 130 C45 120 50 100 100 108 S165 85 200 98 S260 60 300 75 S360 64 400 57 S455 34 500 42 L500 180 L0 180Z" fill="#dcebe2" opacity=".55"/></svg><div className="months"><span>May</span><span>Jun</span><span>Jul</span><span>Aug</span><span>Sep</span><span>Oct</span></div></div></div></section></div>;
}
